/// <summary>
/// Base class for PricingAttribute table <c>METSalesLine</c>
/// </summary>
internal abstract class METGUPPricingAttributeMETSalesLine extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
/// <summary>
/// Get table record of METSalesLine
/// </summary>
/// <param name="_pricingObject">
/// The <c>Common</c> object that will be used to get the table record
/// </param>
/// <returns><c>METSalesLine</c> object</returns>
protected METSalesLine getTableRecord(Common _pricingObject)
{
    SalesLine salesLineLocal = _pricingObject as SalesLine;
    METSalesLine metSalesLine = METSalesLine::find(salesLineLocal.RecId);     
    return metSalesLine;
}

/// <summary>
/// Get value datasource identifier table string
/// </summary>
/// <returns>table name string</returns>
public str getQueryBuilderDatasourceIdentifier()
{
    return tableStr(METSalesLine);
}

/// <summary>
/// Get the table name
/// </summary>
/// <returns>
/// Returns a TableName object
/// </returns>
public TableName getTableName()
{
    return tableStr(METSalesLine);
}

/// <summary>
/// Path of the attribute field.
/// </summary>
/// <returns>Path of the attribute</returns>
public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2',
        tableStr(METSalesLine),
        this.getAttributeFieldIdentifier());

}

/// <summary>
/// Builds pricing object query
/// </summary>
/// <param name="_query">
/// The <c>Query</c> object that the new ranges will be added to.
/// </param>
/// <param name="_value">
/// The <c>anytype</c> object that determines the METInventItemOrderSetup record.
/// </param>
/// <param name="_qdbsMap">
/// The <c>Map</c> object that is used to identify the query build data source.
/// </param>
/// <returns><c>Query</c> object</returns>
public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}

/// <summary>
/// Get value query build datasource object
/// </summary>
/// /// <param name="_query">
/// The <c>Query</c> object that will be used to generate query datasource
/// </param>
/// /// <param name="_qbdsMap">
/// The <c>Map</c> object that will be used to manage categories
/// </param>
/// <returns><c>QueryBuildDataSource</c> object</returns>
protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot;
    QueryBuildDataSource qbds;

    if (_qbdsMap && _qbdsMap.exists(tableStr(SalesLine)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(SalesLine));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(SalesLine));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(SalesLine), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(METSalesLine));
        qbds.addLink(fieldNum(SalesLine, RecId), fieldNum(METSalesLine, SalesLine));
        qbds.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}
